try{/*EXEC v2*/!function(){if("/executive-team"===location.pathname.replace(/\/+$/,"")){var e=[{id:"elsie-benitez",name:"Elsie Benitez",title:"Managing Broker, Orlando Office",img:"https://cdn.prod.website-files.com/6818e202bcb58913b92ece29/6ab5538acfa94cfcb88ee98b_elsie-benitez-headshot.webp",pos:"50% 20%",bio:"Elsie Benitez leads the Goyal &amp; DeCoster Orlando office as Managing Broker. She has spent 20 years helping people buy, sell and care for homes across Greater Orlando, and her work is built on honesty and steady communication. She makes sure every client understands their options and feels supported from the first conversation through closing.<br><br>Elsie founded Benitez Royal Realty as a boutique firm on purpose, so that every client would get real attention. Today the firm handles residential property management, luxury sales and strategic advising for homeowners and investors throughout Central Florida. Before starting her own brokerage, she spent eleven years with Premier Sotheby’s International Realty, working with homes of every size and price, from first homes to some of the region’s finest luxury properties. As a Certified Negotiation Expert (CNE), she knows how to fight hard for her clients at the table. As a Certified Life Coach, she knows that buying or selling a home is rarely just about the house. Clients get a tough negotiator and someone who will walk them calmly through one of the biggest decisions of their lives.<br><br>Elsie was born in Brooklyn and grew up between Brooklyn, New York and Puerto Rico. She began her career at the United Nations in New York City, where she spent eleven years working with ambassadors, international delegations and world leaders, and learned to be gracious under pressure. She holds a B.A. in Education and Business and put both to work when she returned to Puerto Rico and founded a post-secondary college, accredited by the U.S. Department of Education and approved for Pell Grants. That same discipline and cross-cultural ease now serve families, luxury homeowners and investors from all over the world who are making Central Florida home.<br><br>Faith and family come first for Elsie, and service is at the heart of what she does. At Goyal &amp; DeCoster, her goal is simple: bring world-class expertise to every client and make real estate feel personal again."}];"loading"!==document.readyState?t():document.addEventListener("DOMContentLoaded",t)}function t(){if(!document.querySelector("[data-gdc-exec]")){var t=[].slice.call(document.querySelectorAll("section h1")).filter(function(e){return"Raj Goyal"===(e.textContent||"").trim()})[0];if(t){var r=t.closest("section");if(r){var o=r;e.forEach(function(e){var t=r.cloneNode(!0);t.setAttribute("data-gdc-exec",e.name),t.removeAttribute("data-w-id"),[].slice.call(t.querySelectorAll("[data-w-id],[id]")).forEach(function(e){e.removeAttribute("data-w-id"),e.removeAttribute("id")}),t.id=e.id;var a=t.querySelector(".container-19");a&&(a.style.backgroundImage="url('"+e.img+"')",a.style.backgroundPosition=e.pos,a.style.backgroundSize="cover",a.setAttribute("role","img"),a.setAttribute("aria-label",e.name));var n=t.querySelector("h1");n&&(n.textContent=e.name);var i=t.querySelector("h3");i&&(i.textContent=e.title);var s=t.querySelector(".container-20"),l=s&&s.querySelector("p");l&&e.bio?l.innerHTML=e.bio:s&&s.parentNode.removeChild(s),o.parentNode.insertBefore(t,o.nextSibling),o=t})}}}}}()}catch(e){console.error("gdc footer block 14",e)}
